// The committed GraphQL fixtures: regenerated byte-for-byte by make-fixtures.mjs, and every one goes through
// the whole data-core pipeline (parse -> stitch -> restore typenames -> classify -> extract) as its manifest says.

import { test, describe } from "node:test";
import assert from "node:assert/strict";
import { parseLines, stitch } from "../../../src/data/jsonl.js";
import { restoreTypenames } from "../../../src/data/typenames.js";
import { createClassifier } from "../../../src/data/classify.js";
import { extractStory, extractComment } from "../../../src/data/extract.js";
import { buildFixtureFiles, buildFeedResponse, buildFeedPayloads, buildEdge, buildStory, buildSjsBlocks, buildPreloaderBlock, pymkUnit, PEOPLE, PRELOADER_ID, STREAM_LABEL, PAGE_INFO_LABEL } from "../../fixtures/gql/make-fixtures.mjs";
import { readFixture, readJson, feedEdges, sjsPayloads } from "./helpers.mjs";

const manifest = readJson("manifest.json");

function pipelineData(entry) {
  const text = readFixture(entry.file);
  const payloads = entry.kind === "sjs" ? sjsPayloads(text.trim().split("\n").map((l) => JSON.parse(l))) : parseLines(text);
  const { data } = stitch(payloads);
  if (entry.env) restoreTypenames(data, readJson(entry.env).q9k7m2x);
  return data;
}

describe("committed fixtures", () => {
  test("make-fixtures.mjs regenerates every committed file byte-for-byte", () => {
    const files = buildFixtureFiles();
    assert.ok(files.length >= 25);
    for (const { file, content } of files) assert.equal(readFixture(file), content, `${file} is stale: run node test/fixtures/gql/make-fixtures.mjs`);
  });

  test("the generator is deterministic", () => {
    assert.deepEqual(buildFixtureFiles(), buildFixtureFiles());
  });

  test("the manifest covers every classifier outcome", () => {
    const reasons = new Set(manifest.flatMap((m) => m.expect.flatMap((e) => [e.reason, e.hideAI?.reason])).filter(Boolean));
    for (const r of ["keep", "sponsored-data", "category:SPONSORED", "sponsored-label", "auction-distance", "unit:ShowcaseFeedUnit", "unit:PaginatedPeopleYouMayKnowFeedUnit", "unit:AdsSideFeedUnit", "unconnected", "recommended", "follow-suggestion", "join-suggestion", "ai"]) {
      assert.ok(reasons.has(r), r);
    }
  });

  for (const entry of manifest.filter((m) => m.kind !== "comments")) {
    test(`${entry.file}: classify and extract as the manifest says`, async () => {
      const edges = feedEdges(pipelineData(entry));
      assert.equal(edges.length, entry.expect.length);
      const plain = createClassifier();
      const strict = createClassifier({ hideAI: true });
      for (const [i, edge] of edges.entries()) {
        const expect = entry.expect[i];
        const verdict = await plain.classify(edge);
        assert.equal(verdict.keep, expect.keep, `edge ${i}`);
        assert.equal(verdict.reason, expect.reason, `edge ${i}`);
        if ("category" in expect) assert.equal(verdict.category, expect.category, `edge ${i}`);
        if (expect.hideAI) assert.equal((await strict.classify(edge)).reason, expect.hideAI.reason);
        if (verdict.keep) {
          const story = extractStory(edge.node, { sources: ["friends"] });
          assert.equal(story.key, edge.node.post_id);
          assert.ok(story.actors.length && story.avatar && story.url && story.time && story.feedback.id, `edge ${i} renders`);
        }
      }
    });
  }

  test("comments.json: every comment extracts", () => {
    const comments = readJson("comments.json").data.node.comment_rendering_instance_for_feed_location.comments;
    const out = comments.edges.map((e) => extractComment(e.node));
    assert.equal(out.length, 2);
    assert.ok(out.every((c) => c.id && c.author.name && c.text && c.time));
    assert.equal(comments.page_info.has_next_page, false);
  });
});

describe("builders for other packages", () => {
  test("buildFeedResponse: root line, one stream line per further edge, page_info last", () => {
    const body = buildFeedResponse({ stories: [buildStory({ postId: "1", actor: PEOPLE.alice, text: "a" }), buildEdge(pymkUnit()), buildStory({ postId: "2", actor: PEOPLE.bob, text: "b" })], cursor: "C2", hasNext: false });
    assert.ok(body.endsWith("\n"));
    const lines = parseLines(body);
    assert.equal(lines.length, 4);
    assert.equal(lines[0].data.viewer.news_feed.edges.length, 1);
    assert.deepEqual(lines.slice(1, 3).map((l) => [l.label, l.path]), [
      [STREAM_LABEL, ["viewer", "news_feed", "edges", 1]],
      [STREAM_LABEL, ["viewer", "news_feed", "edges", 2]],
    ]);
    assert.equal(lines[3].label, PAGE_INFO_LABEL);
    assert.deepEqual(lines[3].data.page_info, { __typename: "PageInfo", end_cursor: "C2", has_next_page: false });
    assert.equal(lines[3].extensions.is_final, true);
    const { data } = stitch(lines);
    assert.deepEqual(feedEdges(data).map((e) => e.node.__typename), ["Story", "PaginatedPeopleYouMayKnowFeedUnit", "Story"]);
  });

  test("buildFeedResponse with no stories is an empty, final page", () => {
    const { data, final } = stitch(parseLines(buildFeedResponse({ stories: [], hasNext: false })));
    assert.deepEqual(data.viewer.news_feed.edges, []);
    assert.equal(data.viewer.news_feed.page_info.has_next_page, false);
    assert.equal(final, true);
  });

  test("buildEdge: organic stories get a real ORGANIC hash; units get none", () => {
    const edge = buildEdge(buildStory({ postId: "5", actor: PEOPLE.alice, text: "x" }));
    assert.match(edge.cat_sensitive.enc, /^[0-9a-f]{64}$/);
    assert.equal(edge.cat_sensitive.cat, null);
    assert.equal(edge.sposnsor_new_distac_action, null);
    assert.deepEqual(buildEdge(pymkUnit()).cat_sensitive, { enc: null, cat: null });
  });

  test("SSR builders: a preloader descriptor and stream-cache blocks keyed by the same preloader id", () => {
    const pre = buildPreloaderBlock({ feedStyle: "MOST_RECENT_FRIENDS_FEED", orderby: ["MOST_RECENT"] });
    const descriptor = pre.require[0][3][0].preloaders[0];
    assert.equal(descriptor.queryName, "CometModernHomeFeedQuery");
    assert.equal(descriptor.preloaderID, PRELOADER_ID);
    assert.equal(descriptor.variables.feedStyle, "MOST_RECENT_FRIENDS_FEED");
    const blocks = buildSjsBlocks(buildFeedPayloads({ stories: [buildStory({ postId: "1", actor: PEOPLE.alice, text: "a" })] }));
    const entry = blocks[0].require[0][3][0].__bbox.require[0];
    assert.equal(entry[0], "RelayPrefetchedStreamCache");
    assert.equal(entry[3][0], PRELOADER_ID);
    assert.match(blocks[1].require[0][3][0].__bbox.require[0][0], /^RelayPrefetchedStreamCache@/);
    assert.equal(blocks.at(-1).require[0][3][0].__bbox.require[0][3][1].__bbox.complete, true);
  });
});
